HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SSVT — Super Sonic Video Tube</title><link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#0b1020">
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#131b2f;--panel2:#19243b;--text:#f2f5fb;--muted:#aab5c9;--accent:#7c9cff;--line:#2b3853}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(150deg,#0b1020,#11182a);color:var(--text);font:15px/1.5 system-ui,Segoe UI,Arial,sans-serif}
header{position:sticky;top:0;background:#0b1020ee;border-bottom:1px solid var(--line);padding:14px 4vw;display:flex;align-items:center;gap:12px;flex-wrap:wrap;z-index:2}
.brand{font-weight:850;font-size:1.25rem}.brand span{color:var(--accent)}input,textarea,button{font:inherit;border-radius:10px;border:1px solid var(--line);padding:10px 12px;background:var(--panel);color:var(--text)}input,textarea{width:100%}button{cursor:pointer;background:var(--accent);border-color:transparent;color:#071027;font-weight:700}button.secondary{background:var(--panel2);color:var(--text);border-color:var(--line)}.search{flex:1;min-width:180px;max-width:560px}.muted{color:var(--muted)}main{max-width:1280px;margin:auto;padding:26px 4vw 60px}.nav{display:flex;gap:14px;align-items:center}.nav a{color:var(--muted);text-decoration:none}.nav a:hover{color:var(--text)}.login-link{color:#071027;background:var(--accent);padding:10px 13px;border-radius:10px;text-decoration:none;font-weight:750;white-space:nowrap}.hero{min-height:230px;display:flex;align-items:center}.hero-copy{max-width:680px}.hero-art{margin-left:auto;font-size:clamp(4rem,12vw,8rem);filter:drop-shadow(0 12px 28px #526ed955)}.section-head{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin:26px 0 12px}.chips{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 18px}.chip{background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:99px;padding:8px 13px}.chip.active{background:var(--accent);color:#071027}.thumb{height:145px;display:grid;place-items:center;border-radius:12px;background:linear-gradient(135deg,#1c2b4a,#384d7a);font-size:3rem;margin-bottom:12px}.video-card video{aspect-ratio:16/9;object-fit:contain}.video-card h3{margin:8px 0}.login-page main{max-width:980px}.login-hero{max-width:760px;margin:18px auto}.login-hero .forms{margin-top:18px}.auth-card{min-width:0;border:1px solid var(--line);border-radius:14px;background:linear-gradient(160deg,#17223a,#111a2d);padding:20px}.auth-card h3{margin-top:0;font-size:1.2rem}.auth-card .field label{font-size:.92rem;color:#dce4f4}.auth-card input{min-height:44px}.auth-card button{width:100%;min-height:44px;margin-top:8px}.auth-card button:disabled{opacity:.65;cursor:wait}.form-status{min-height:22px;margin:10px 0 0;font-size:.9rem;white-space:pre-wrap}.form-status.error{color:#ff9caa}.form-status.success{color:#9de6bc}.form-status.info{color:#c4d2ff}.field-hint{font-size:.8rem;color:var(--muted);margin-top:-2px}@media(max-width:720px){.nav{order:4;flex-basis:100%;justify-content:space-around}.hero-art{display:none}.login-link{margin-left:auto}}.hero{padding:24px;border:1px solid var(--line);border-radius:18px;background:radial-gradient(circle at 90% 10%,#2b3e6b 0,transparent 35%),var(--panel);margin-bottom:24px}.hero h1{font-size:clamp(1.7rem,4vw,2.6rem);line-height:1.1;margin:0 0 12px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}.card,.panel{border:1px solid var(--line);border-radius:16px;background:var(--panel);padding:18px}.panel{margin:18px 0}.forms{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.field{display:grid;gap:6px;margin:10px 0}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.status{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:3px 9px;color:var(--muted);font-size:.8rem}.notice{margin:14px 0;padding:12px;border-radius:10px;background:var(--panel2);white-space:pre-wrap}.small{font-size:.86rem}.hide{display:none}.video-icon{height:120px;display:grid;place-items:center;border-radius:12px;background:linear-gradient(135deg,#1e2b48,#2d416d);font-size:2.5rem}h2{margin-top:0}@media(max-width:600px){header{padding:12px 4vw}.search{order:3;max-width:none;flex-basis:100%}.hero{padding:18px}}
</style></head><body>
<header><a class="brand" href="/" style="text-decoration:none;color:var(--text)">SSVT <span>▶</span></a><nav class="nav"><a href="#recent">Recent</a><a href="#viral">Viral</a><a href="#categories">Categories</a></nav><input id="search" class="search" placeholder="Search videos" aria-label="Search videos"><button id="searchButton" type="button" onclick="loadVideos()">Search</button><a class="login-link" href="/login">Log in / Sign up</a></header>
<main id="homePage"><section class="hero"><div class="hero-copy"><h1>Discover videos. Find your next favourite.</h1><p class="muted">Welcome to SSVT — your video community. Explore the latest uploads, browse categories and discover featured picks. Creator uploads are reviewed before publishing.</p><div class="row"><a class="login-link" href="/login">Join SSVT</a><span class="status">16+ creator accounts</span><span class="status">Community moderation</span></div></div><div class="hero-art" aria-hidden="true">▶</div></section>
<div id="notice" class="notice hide" role="status"></div>
<section id="auth" class="panel hide login-hero"><h2>Welcome to SSVT</h2><p class="muted">Log in to your account or create an invite-only creator account.</p><div class="forms">
<form id="loginForm" class="auth-card"><h3>Welcome back</h3><p class="muted small">Log in to continue to your Creator Studio.</p><div class="field"><label for="loginEmail">Email address</label><input id="loginEmail" name="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field"><label for="loginPassword">Password</label><input id="loginPassword" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required></div><button id="loginButton" type="submit">Log in</button><p id="loginStatus" class="form-status" role="status" aria-live="polite"></p></form>
<form id="registerForm" class="auth-card"><h3>Create your account</h3><p class="muted small">Creator registration is invite-only and available to users aged 16+.</p><div class="field"><label for="regName">Display name</label><input id="regName" name="display_name" minlength="2" maxlength="60" autocomplete="name" placeholder="Your name" required></div><div class="field"><label for="regUsername">Username</label><input id="regUsername" name="username" pattern="[a-zA-Z0-9_]{3,24}" autocomplete="username" placeholder="letters, numbers, underscore" required><span class="field-hint">3–24 characters; letters, numbers and underscore.</span></div><div class="field"><label for="regEmail">Email address</label><input id="regEmail" name="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field"><label for="regDob">Date of birth (16+)</label><input id="regDob" name="date_of_birth" type="date" autocomplete="bday" required></div><div class="field"><label for="regPassword">Create password</label><input id="regPassword" name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="At least 10 characters" required><span class="field-hint">Use a unique password. It is hashed by the server.</span></div><div class="field"><label for="inviteCode">Invite code</label><input id="inviteCode" name="invite_code" type="password" autocomplete="off" placeholder="Enter your private invite code" required></div><div class="field"><label style="display:flex;gap:9px;align-items:flex-start"><input name="terms_accepted" type="checkbox" value="true" required style="width:18px;min-width:18px;min-height:18px;margin-top:3px"> <span>I am 16 or older and accept the <a href="#terms" style="color:var(--accent)">Terms & Conditions</a>, Copyright Rules and Community Safety Policy.</span></label></div><button id="registerButton" type="submit">Create creator account</button><p id="registerStatus" class="form-status" role="status" aria-live="polite"></p></form></div></section>
<section id="account" class="panel hide"><div class="row"><h2 id="welcome">Creator Studio</h2><button class="secondary" onclick="logout()">Log out</button></div><p class="muted">Quota: 2 videos per creator; max 50 MB each. Uploads stay pending review.</p>
<form id="uploadForm"><div class="field"><label>Video title</label><input name="title" minlength="3" maxlength="120" required></div><div class="field"><label>Description</label><textarea name="description" maxlength="2000" rows="3"></textarea></div><div class="field"><label>Video file (MP4, WEBM, MOV; max 50 MB)</label><input name="file" type="file" accept=".mp4,.webm,.mov,video/mp4,video/webm,video/quicktime" required></div><button>Upload for review</button></form><h3>My uploads</h3><div id="myVideos" class="grid"></div></section>
<section id="recent"><div class="section-head"><h2>Recent videos</h2><span class="muted small">Newest published uploads</span></div><div id="videos" class="grid"></div></section>
<section id="viral"><div class="section-head"><h2>Viral videos</h2><span class="muted small">Featured picks · popularity metrics coming later</span></div><div id="viralVideos" class="grid"></div></section>
<section id="categories"><div class="section-head"><h2>Browse categories</h2><span class="muted small">Choose a topic to filter videos</span></div><div class="chips" id="categoryChips"><button class="chip active" data-category="All" onclick="setCategory('All')">All</button><button class="chip" data-category="Music" onclick="setCategory('Music')">Music</button><button class="chip" data-category="Gaming" onclick="setCategory('Gaming')">Gaming</button><button class="chip" data-category="Education" onclick="setCategory('Education')">Education</button><button class="chip" data-category="Technology" onclick="setCategory('Technology')">Technology</button><button class="chip" data-category="Entertainment" onclick="setCategory('Entertainment')">Entertainment</button><button class="chip" data-category="Lifestyle" onclick="setCategory('Lifestyle')">Lifestyle</button></div><div id="categoryVideos" class="grid"></div></section>
<section class="panel" id="admin"><h2>Admin & Team Console</h2><p class="muted small">Restricted. Enter the server-side SSVT_ADMIN_TOKEN. Never share it with users or put it in public screenshots. Team members should be given limited permissions in a production RBAC implementation.</p><div class="field"><label>Admin token</label><input id="adminToken" type="password" autocomplete="off" placeholder="Server admin token"></div><div class="row"><button type="button" onclick="adminLoadUsers()">Load users</button><button class="secondary" type="button" onclick="adminLoadVideos()">Load videos</button><button class="secondary" type="button" onclick="adminLoadAudit()">Audit log</button></div><div id="adminResults" class="grid" style="margin-top:14px"></div></section>
<section class="panel" id="terms"><h2>Terms & Conditions / Copyright</h2><p><b>Company:</b> AI Software Innovation Infotech and Hardware Enterprises & Artificial Intelligence.</p><p>SSVT is intended only for users aged 16 or older. Users must upload only videos they own or are authorized to distribute. Pornographic, sexually explicit, exploitative, illegal, or otherwise prohibited content is not allowed. Uploads may be reviewed, rejected, removed, or escalated. Serious or repeated violations may result in warnings, account blocking, or deletion.</p><p>Users retain rights to their original content and grant the platform only the limited permissions necessary to host, review, stream, and moderate that content. Do not upload copyrighted material without permission. Report suspected infringement to the platform administrator.</p><p>Copyright © 2026 AI Software Innovation Infotech and Hardware Enterprises & Artificial Intelligence. All rights reserved. SSVT prototype; these terms are a starter template and should be reviewed by a qualified legal professional before public launch.</p><p class="muted small">Content screening currently checks metadata and requires manual review. It cannot reliably identify every prohibited visual in a video. Do not treat this prototype as a complete safety or legal compliance system.</p></section>
<section class="panel" id="chatbot"><h2>SSVT AI Chatbot</h2><p class="muted small">LLM requests are disabled until an approved provider is configured on the server. Do not paste passwords or private information.</p><form id="chatForm"><div class="field"><label>Ask about videos, captions or using SSVT</label><textarea name="message" maxlength="4000" rows="3" required placeholder="Ask a question…"></textarea></div><button>Send message</button></form><div id="chatReply" class="notice hide"></div></section>
<section class="panel" id="android"><h2>Install on Android</h2><p class="muted">When hosted over HTTPS, open this site in Chrome → menu (⋮) → “Install app” or “Add to Home screen”. This creates an installable web app; it is not an APK download. Native APK build instructions are in the install guide.</p><a href="/manifest.webmanifest" style="color:var(--accent)">View app manifest</a></section>
<section class="panel"><h2>Prototype boundaries</h2><p class="muted small">No adaptive streaming, 720p transcoding, email verification or authenticity proof is implemented yet. “Unverified” must never be treated as “fake.”</p></section></main>
<script>
let token=sessionStorage.getItem("ssvt_token")||"";let allVideos=[];let activeCategory="All";const $=id=>document.getElementById(id);if("serviceWorker" in navigator){navigator.serviceWorker.register("/service-worker.js").catch(()=>{});}
function notify(s){$("notice").textContent=s;$("notice").classList.remove("hide")}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function api(path,opts={}){opts.headers=opts.headers||{};if(token)opts.headers.Authorization="Bearer "+token;let r=await fetch(path,opts),d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||"Request failed");return d}
function categoryOf(v){const t=(v.title+" "+(v.description||"")).toLowerCase();if(/music|song|sing|cover|dance|dj/.test(t))return "Music";if(/game|gaming|playthrough|esports/.test(t))return "Gaming";if(/learn|lesson|tutorial|study|course|education/.test(t))return "Education";if(/tech|ai|software|computer|coding|phone|gadget/.test(t))return "Technology";if(/vlog|comedy|funny|movie|show|entertainment/.test(t))return "Entertainment";if(/travel|food|fitness|daily|life|fashion/.test(t))return "Lifestyle";return "Other"}
function videoCard(v){return `<article class="card video-card"><video controls preload="none" style="width:100%;border-radius:12px;background:#050812" src="/api/v1/videos/${v.id}/stream"></video><h3>${esc(v.title)}</h3><p class="muted small">${esc(v.description||"No description")}</p><p class="small">By <b>${esc(v.display_name)}</b> · @${esc(v.username)} · ${categoryOf(v)}</p></article>`}
function renderVideoGroups(items){const empty='<div class="card muted">No published videos yet. Be the first creator to upload.</div>';$("videos").innerHTML=items.length?items.map(videoCard).join(""):empty;$("viralVideos").innerHTML=items.length?items.slice(0,6).map(videoCard).join(""):'<div class="card muted">Featured picks will appear when videos are published. Popularity ranking is planned for a future update.</div>';const cat=activeCategory==="All"?items:items.filter(v=>categoryOf(v)===activeCategory);$("categoryVideos").innerHTML=cat.length?cat.map(videoCard).join(""):'<div class="card muted">No videos in this category yet.</div>'}
function setCategory(c){activeCategory=c;document.querySelectorAll("[data-category]").forEach(b=>b.classList.toggle("active",b.dataset.category===c));renderVideoGroups(allVideos)}
async function loadVideos(){try{let q=$("search").value.trim(),d=await api("/api/v1/videos"+(q?"?q="+encodeURIComponent(q):""));allVideos=d.items||[];renderVideoGroups(allVideos)}catch(e){notify(e.message)}}
async function loadAccount(){if(!token){$("account").classList.add("hide");return}try{let u=await api("/api/v1/auth/me");$("account").classList.remove("hide");$("welcome").textContent="Creator Studio · "+u.display_name;await loadMine()}catch(e){logout()}}
async function loadMine(){try{let d=await api("/api/v1/videos/mine");$("myVideos").innerHTML=d.items.length?d.items.map(v=>`<article class="card"><h3>${esc(v.title)}</h3><span class="status">${esc(v.status)}</span><p class="muted small">${Math.round(v.file_size/1048576*10)/10} MB</p></article>`).join(""):'<p class="muted">No uploads yet.</p>'}catch(e){notify(e.message)}}
function setFormStatus(id,message,kind="info"){const el=$(id);if(!el)return;el.textContent=message;el.className="form-status"+(kind?" "+kind:"")}
function setBusy(buttonId,busy,label){const b=$(buttonId);if(!b)return;if(busy){b.dataset.originalLabel=b.textContent;b.disabled=true;b.textContent=label}else{b.disabled=false;b.textContent=b.dataset.originalLabel||label}}
// Search works with either the button or Enter key; errors remain visible on the page.
$("search").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();loadVideos()}});
$("loginForm").addEventListener("submit",async e=>{e.preventDefault();setFormStatus("loginStatus","Checking your login…");setBusy("loginButton",true,"Logging in…");try{let d=await api("/api/v1/auth/login",{method:"POST",body:new FormData(e.target)});token=d.access_token;sessionStorage.setItem("ssvt_token",token);$("auth").classList.add("hide");notify("Login successful.");await loadAccount()}catch(err){setFormStatus("loginStatus",err.message,"error")}finally{setBusy("loginButton",false,"Log in")}});
$("registerForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;setFormStatus("registerStatus","Validating details and creating your account…");setBusy("registerButton",true,"Creating account…");try{let d=await api("/api/v1/auth/register",{method:"POST",body:new FormData(f)});token=d.access_token;sessionStorage.setItem("ssvt_token",token);$("auth").classList.add("hide");notify("Account created successfully. Keep your invite code private.");await loadAccount()}catch(err){setFormStatus("registerStatus",err.message,"error")}finally{setBusy("registerButton",false,"Create creator account")}});
$("uploadForm").addEventListener("submit",async e=>{e.preventDefault();try{let d=await api("/api/v1/videos/upload",{method:"POST",body:new FormData(e.target)});notify(d.message);e.target.reset();await loadMine()}catch(err){notify(err.message)}});
$("chatForm").addEventListener("submit",async e=>{e.preventDefault();const reply=$("chatReply");reply.textContent="Thinking…";reply.classList.remove("hide");try{const fd=new FormData(e.target);const d=await api("/api/v1/ai/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:fd.get("message")})});reply.textContent=d.reply;}catch(err){reply.textContent=err.message;}});
function logout(){token="";sessionStorage.removeItem("ssvt_token");$("account").classList.add("hide");notify("Logged out.")}
function adminHeaders(){return {"X-Admin-Token":$("adminToken").value.trim()}}
async function adminLoadUsers(){try{let r=await fetch("/api/v1/admin/users",{headers:adminHeaders()});let d=await r.json();if(!r.ok)throw Error(d.detail||"Admin request failed");$("adminResults").innerHTML=d.items.map(u=>`<article class="card"><h3>${esc(u.display_name)} (@${esc(u.username)})</h3><p>${esc(u.email)} · ${esc(u.role)} · ${esc(u.account_status)}</p><div class="row"><button onclick="adminUserStatus(${u.id},'warned')">Warn</button><button onclick="adminUserStatus(${u.id},'blocked')">Block</button><button class="secondary" onclick="adminUserStatus(${u.id},'active')">Unblock</button><button class="secondary" onclick="adminUserStatus(${u.id},'deleted')">Delete</button><button class="secondary" onclick="adminRecreate(${u.id})">Recreate</button></div><p class="small muted">${esc(u.account_note||"")}</p></article>`).join("")||"No users"}catch(e){notify(e.message)}}
async function adminUserStatus(id,status){let note=prompt("Reason / warning for audit log (optional):")||"";let fd=new FormData();fd.set("status",status);fd.set("note",note);try{let r=await fetch(`/api/v1/admin/users/${id}/status`,{method:"POST",headers:adminHeaders(),body:fd});let d=await r.json();if(!r.ok)throw Error(d.detail||"Admin request failed");notify(`User ${id}: ${status}`);await adminLoadUsers()}catch(e){notify(e.message)}}
async function adminRecreate(id){try{let r=await fetch(`/api/v1/admin/users/${id}/recreate`,{method:"POST",headers:adminHeaders()});let d=await r.json();if(!r.ok)throw Error(d.detail||"Admin request failed");await adminLoadUsers()}catch(e){notify(e.message)}}
async function adminLoadVideos(){try{let r=await fetch("/api/v1/admin/videos",{headers:adminHeaders()});let d=await r.json();if(!r.ok)throw Error(d.detail||"Admin request failed");$("adminResults").innerHTML=d.items.map(v=>`<article class="card"><h3>#${v.id} ${esc(v.title)}</h3><p>${esc(v.email)} · ${esc(v.status)} · ${Math.round(v.file_size/1048576*10)/10} MB</p><div class="row"><a style="color:var(--accent)" href="/api/v1/admin/videos/${v.id}/download" onclick="event.preventDefault();adminDownload(${v.id})">Download</a><button onclick="adminModerate(${v.id},'published')">Publish</button><button class="secondary" onclick="adminModerate(${v.id},'rejected')">Reject</button><button class="secondary" onclick="adminDeleteVideo(${v.id})">Delete</button><button class="secondary" onclick="adminTrim(${v.id})">Trim</button></div></article>`).join("")||"No videos"}catch(e){notify(e.message)}}
async function adminDownload(id){try{let r=await fetch(`/api/v1/admin/videos/${id}/download`,{headers:adminHeaders()});if(!r.ok){let d=await r.json();throw Error(d.detail||"Download failed")}let blob=await r.blob(),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`ssvt-video-${id}`;a.click();URL.revokeObjectURL(a.href)}catch(e){notify(e.message)}}
async function adminModerate(id,status){let fd=new FormData();fd.set("status",status);try{let r=await fetch(`/api/v1/admin/videos/${id}/moderate`,{method:"POST",headers:adminHeaders(),body:fd});let d=await r.json();if(!r.ok)throw Error(d.detail||"Moderation failed");await adminLoadVideos()}catch(e){notify(e.message)}}
async function adminDeleteVideo(id){if(!confirm("Permanently delete this video?"))return;try{let r=await fetch(`/api/v1/admin/videos/${id}`,{method:"DELETE",headers:adminHeaders()});let d=await r.json();if(!r.ok)throw Error(d.detail||"Delete failed");await adminLoadVideos()}catch(e){notify(e.message)}}
async function adminTrim(id){let start=prompt("Trim start time in seconds (e.g. 0):");if(start===null)return;let end=prompt("Trim end time in seconds:");if(end===null)return;let fd=new FormData();fd.set("start_seconds",start);fd.set("end_seconds",end);try{let r=await fetch(`/api/v1/admin/videos/${id}/trim`,{method:"POST",headers:adminHeaders(),body:fd});let d=await r.json();if(!r.ok)throw Error(d.detail||"Trim failed");notify(d.note||"Trim complete");await adminLoadVideos()}catch(e){notify(e.message)}}
async function adminLoadAudit(){try{let r=await fetch("/api/v1/admin/audit",{headers:adminHeaders()});let d=await r.json();if(!r.ok)throw Error(d.detail||"Audit request failed");$("adminResults").innerHTML=d.items.map(a=>`<article class="card"><b>${esc(a.action)}</b><p>${esc(a.actor)} · user ${esc(a.target_user_id)} · video ${esc(a.target_video_id)}</p><p class="muted small">${esc(a.note)} · ${esc(a.created_at)}</p></article>`).join("")||"No audit events"}catch(e){notify(e.message)}}
const dobInput=$("regDob");if(dobInput)dobInput.max=new Date().toISOString().slice(0,10);
if(location.pathname==="/login"){document.body.classList.add("login-page");$("homePage").classList.add("hide");["recent","viral","categories"].forEach(id=>$(id).classList.add("hide"));$("auth").classList.remove("hide");document.title="Log in / Sign up · SSVT";}loadVideos();loadAccount();
</script></body></html>"""
